import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"1、【乾】 乾下乾上","description":"周易阐真 - 1、【乾】 乾下乾上","frontmatter":{"title":"1、【乾】 乾下乾上","description":"周易阐真 - 1、【乾】 乾下乾上"},"headers":[],"relativePath":"zh/classics/chanzhen/002.md","filePath":"zh/classics/chanzhen/002.md"}'),s={name:"zh/classics/chanzhen/002.md"};function n(c,p,i,o,h,l){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：大哉乾元，万物资始，乃统天。云行雨施，品物流形。大明终始，六位时成，时乘六龙以御天。乾道变化，各正性命，保合太和，乃利贞。首出庶物，万国咸宁。</p></blockquote><h1 id="_1、【乾】-乾下乾上" tabindex="-1">1、【乾】 乾下乾上 <a class="header-anchor" href="#_1、【乾】-乾下乾上" aria-label="Permalink to “1、【乾】 乾下乾上”">​</a></h1><p>初九：潜龙勿用。</p><p>九二：见龙在田，利见大人。</p><p>九三：君子终日乾乾，夕惕若，厉，无咎。</p><p>九四：或跃在渊，无咎。</p><p>九五：飞龙在天，利见大人。</p><p>上九：亢龙有悔。</p><p>用九：见群龙无首，吉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：天行健，君子以自强不息。</p><p>乾为天，其德健。上乾天，下乾天，是天之一气，上下流行不息，行健之象也。</p><p>君子有见于此，知人资天之气而始，即有此天之健德，此德本来流行不息，无一时间断，因交后天，弃真入假，健非所健，有时间断矣。以是效天之行健，借假修真，于后天中返先天，自强不息焉。强者，刚强不屈，万物难移之谓。若能自强，则正气长存，内有主宰，富贵不能淫，贫贱不能移，威武不能屈，非礼不履，非道不处，非义不行，顺之逆之，强而无处不在，强而无时或息，其行与天为徒矣。但世之强者有矣，强而为物所引，用之于外者有矣。或能自强，始勤终怠，遵道而行，半途而废者亦有矣。自强实落功夫，全在不息，若稍有一点懈怠，稍有些子私欲，不得谓强，亦不得谓自强。惟不息之自强，方能造到浑然天理，坚刚不坏，永久长存地位。夫天者，命也。命者，健德，即本来一点浩然正气。因其无影无形，活活泼泼，流行不息，谓之气；因其至大至刚，充塞天地，谓之健；因其主宰万有，为阴阳之祖，造化之根，谓之命。气也，健也，命也，总一强也。一自强不息，而造命之功尽矣，此法天之学也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>乾者，健也，刚强不屈之义。卦体六爻皆奇，纯阳之象，故谓乾。此进阳火之卦，造命之学，所以行健而用刚道也。健莫健于天，天之为道，一气流行，循环无端，经久不已，无物不复，无物能伤，健之至矣。</p><p>故当春而生物者，健之元也。元者，初也，阳气之初生。阳气初生，而万物俱皆萌甲，元何其健乎?</p><p>夏而长物者，健之亨也。亨者，通也，阳气之通畅。阳气通畅，而万物俱皆发旺，亨何其健乎?</p><p>秋而成物者，健之利也。利者，宜也，阳气之便宜。阳气便宜，而万物俱皆成实，利何其健乎?</p><p>冬而藏物者，健之贞也。贞者，静也，阳气之宁静。阳气宁静，而万物俱皆归根，贞何其健乎?</p><p>元、亨、利、贞，四时迭运，总是一健行之，一为体而四为用。体以施用，用以全体，体用如一，故天道健行而不息也。</p><p>惟人也，资天之气而始形，即具此天之健德，即有此元、亨、利、贞之健用。人之健德，即本来之良知、先天之正气，名曰真阳，又曰真一之精，又曰真一之气，儒曰精一，道曰抱一，释曰归一。无非教人修此一点刚健正气耳。</p><p>是气也，本于先天，藏于后天，处圣不增，处凡不减，有生之初，不垢亦不净，不生亦不灭，不色亦不空，寂然不动，感而遂通，处于万物之中，不为万物所屈。本自元，本自亨，本自利，本自贞，皆在无心中运用，不待勉强，出于自然；不健而健，健而不健，健之无形迹可窥，所谓天人者是也。</p><p>一交后天，气质发而外物诱，性相近而习相远，弃真认假，良知有昧。于是元者不元，亨者不亨，利者不利，贞者不贞；健之德已亏，健之用已非，神昏气浊，性乱命摇，身虽动而阳气消，不死岂能之乎?</p><p>故圣人有造命之学，于后天中返先天，能以修持本来乾健之德，永久不坏耳。修持之道，仍不外此元、亨、利、贞之用。</p><p>人能看破一切，猛醒回头，志于性命，恍惚杳冥之中，便有一点生机潜发，此健之元也。人能一心修养，真履实践，经久不殆，行以达其所欲，即健之亨也。人能振发精神，勇力前进，刚气凝聚，诸缘不碍，生死如一，即健之利也。人能格物致知，辨别是非邪正，止于其所而不迁，即健之贞也。</p><p>元以生其健，亨以通其健，利以成其健，贞以固其健。元、亨、利、贞一气运用，由勉强而归自然，浑然天理，仍是良知本来面目，可以与天同功用，与天同长久矣。</p><p>但是道也，有药物，有火候，有功力，有急缓，有止足。修之合法，养之随时，方能进于佳境。倘差之毫发，失之千里。元、亨、利、贞，四者缺一，则健德不成，命非我有。此进阳之火候，不可不知也。</p><p>初九，在健之初，健德方振，如潜藏之龙，正当培养正气之时，未可自恃其健，故曰“勿用”。</p><p>九二，健而得中，不偏不倚，刚柔相当，如见龙在田，生气常存，天良不昧，圣胎有象。所谓大人者，不失其赤子之心者也，故曰“利见”。</p><p>九三，浩气充塞，刚而得正，日则勉于行，夕则察其过，日乾夕惕，健行不息，虽有危厉，故能无咎。</p><p>九四，健德已成，圣胎完全，待时脱化，如龙或跃而起，或在于渊，审查气候，防危虑险，故可无咎。</p><p>九五，刚健中正，阴阳混化，身外有身，形神俱妙，与道合真，不但成己，而且成物，如飞龙在天，隐显不测，随时济物。所谓大人者，正己而正物者也，故曰“利见”。</p><p>上九，进健太过，独刚不柔，知进而不知退，如亢旱之龙，龙至于亢，不能生物。健至太过，必败其事。阳极必阴，天宝得而复失，理有可决，故曰“有悔”。</p><p>大抵行健用刚之道，贵乎随时，随时之健，能刚能柔，元、亨、利、贞，无往而不可健，无往而有伤健矣。</p><p>圣人恐人不知用健之道，大书特书曰：“用九，见群龙无首，吉。”此言太煞分明。九为河图一三五，阳生之数。用九者，即用健也。龙之为灵昭昭也，变化不测，能上能下，能大能小，能隐能显，迎之不见其首，随之不见其后。修健之道，如御龙也。用健而能随时，如群龙之变化也。当潜而潜，当见而见，当乾而乾，当跃而跃，当飞而飞，健而不至过，高而不至亢，缓急止足，各随其时，此无首之健，用之而未有不取吉者。但无首变化之道，须要真知灼见。若不见而猜想做作，虽天宝在望，未许我得。用之必先见之，见而后用，则有用，用中无用，无功，功里施功，有无不立，顺逆不拘，大地里黄芽长遍，满世界金花开绽，信步走去，头头是道，取之左右逢其原，用九而不为九所用，方且进于刚健中正纯粹之精，我命由我不由天，与天为徒矣。</p>',35)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
